CustomField.formula:
IF(
/* ---------- COMPLETE ---------- */ AND( TEXT(LearnerAccount.Student_Type__c) = "Returning", OR( TEXT(TELA_Fee_Verification__c) = "Verified", TEXT(TELA_Fee_Verification__c) = "Waived" ), CONTAINS(TEXT(Student_Info_Contact_Form__c),"V"), CONTAINS(TEXT(Parent_Contract__c),"V"), CONTAINS(TEXT(FERPA_Directory_Info_Notice__c),"V"), CONTAINS(TEXT(Housing_Questionnaire__c),"V"), NOT(ISBLANK(Housing_ATS_Code__c)) ),
"Complete",
IF(
/* ---------- STARTED ---------- */ AND( CONTAINS(TEXT(LearnerAccount.Student_Type__c),"R"), OR( CONTAINS(TEXT(EnrollmentStatus),"2"), CONTAINS(TEXT(EnrollmentStatus),"5") ), OR( CONTAINS(TEXT(TELA_Fee_Form__c),"fi"), CONTAINS(TEXT(TELA_Fee_Verification__c),"fi"), CONTAINS(TEXT(Student_Info_Contact_Form__c),"fi"), CONTAINS(TEXT(Uploaded_IEP__c),"fi"), CONTAINS(TEXT(MAF_Upload__c),"fi"), CONTAINS(TEXT(Parent_Contract__c),"fi"), CONTAINS(TEXT(FERPA_Directory_Info_Notice__c),"fi"), CONTAINS(TEXT(Immunization_Records__c),"fi"), CONTAINS(TEXT(Physical_Upload__c),"fi"), CONTAINS(TEXT(Housing_Questionnaire__c),"fi"), NOT(ISBLANK(Housing_ATS_Code__c)) ) ),
"Started",
IF( TEXT(LearnerAccount.Student_Type__c) = "Returning", "Not Started", "N/A" )
)
)
